@app.cell
def _(mo):
    _title = mo.md(
        "# Интерактивный генератор выборок\n"
        "Генеральная совокупность — **выборка 6000 ресторанов** из полного "
        "набора TripAdvisor. Двигайте ползунки: график и таблица "
        "пересчитываются вживую."
    )
    _title
    return


@app.cell
def _(mo):
    mo.md("[⌂ Главная](index.html) · [☕ Кофе](s1.html) · [🍽️ HoReCa](s2.html)")
    return


@app.cell
def _(mo):
    variable = mo.ui.dropdown(
        {"Рейтинг": "rating", "Число отзывов": "reviews", "ln(число отзывов)": "log"},
        value="Рейтинг",
        label="Величина",
    )
    n = mo.ui.slider(10, 2000, value=300, step=10, label="Размер выборки n", show_value=True)
    replace = mo.ui.checkbox(value=False, label="с возвращением")
    seed = mo.ui.number(0, 9999, value=42, label="seed")
    mo.hstack([variable, n, replace, seed], justify="start", gap=1.5)
    return variable, n, replace, seed


@app.cell
def _(mo, np, plt, POP_RATING, POP_REVIEWS, variable, n, replace, seed,
      BG, PANEL, TEXT, MUTED, ACCENT, SECOND):
    _kind = variable.value
    if _kind == "rating":
        _pop = POP_RATING
        _unit = "рейтинг, баллы"
        _name = "Рейтинг ресторана"
        _bins = np.arange(0.75, 5.75, 0.5)
    elif _kind == "reviews":
        _pop = POP_REVIEWS.astype(np.float64)
        _unit = "число отзывов, шт."
        _name = "Число отзывов"
        _bins = 40
    else:
        _pop = np.log(POP_REVIEWS.astype(np.float64))
        _unit = "ln(число отзывов)"
        _name = "ln(число отзывов)"
        _bins = 40

    _rng = np.random.default_rng(int(seed.value))
    _nn = int(n.value)
    _sample = _rng.choice(_pop, size=_nn, replace=bool(replace.value) or _nn > _pop.size)

    # --- ECDF ---
    def _ecdf(a):
        xs = np.sort(a)
        ys = np.arange(1, len(xs) + 1) / len(xs)
        return xs, ys

    _px, _py = _ecdf(_pop)
    _sx, _sy = _ecdf(_sample)

    _fig, (_ax1, _ax2) = plt.subplots(1, 2, figsize=(10, 4.0))

    _ax1.step(_px, _py, where="post", color=MUTED, lw=1.6,
              label="генеральная (6000)")
    _ax1.step(_sx, _sy, where="post", color=ACCENT, lw=2.0,
              label=f"выборка (n={_nn})")
    _ax1.set_title("Эмпирическая функция распределения")
    _ax1.set_xlabel(_unit)
    _ax1.set_ylabel("доля наблюдений")
    _ax1.legend(facecolor=PANEL, edgecolor=MUTED, labelcolor=TEXT, framealpha=0.9)

    _ax2.hist(_pop, bins=_bins, density=True, color=MUTED, alpha=0.45,
              label="генеральная")
    _ax2.hist(_sample, bins=_bins, density=True, color=SECOND, alpha=0.65,
              label="выборка")
    _ax2.set_title("Гистограмма плотности")
    _ax2.set_xlabel(_unit)
    _ax2.set_ylabel("плотность")
    _ax2.legend(facecolor=PANEL, edgecolor=MUTED, labelcolor=TEXT, framealpha=0.9)

    _fig.suptitle(_name, color=TEXT, fontsize=14)
    _fig.tight_layout()

    # --- Статистика: генеральная vs выборка + ошибка ---
    _pm, _pv = float(np.mean(_pop)), float(np.var(_pop))
    _sm, _sv = float(np.mean(_sample)), float(np.var(_sample, ddof=1))
    _dm = _sm - _pm
    _dv = _sv - _pv

    _table = mo.md(
        f"""
| Показатель | Генеральная (6000) | Выборка (n={_nn}) | Ошибка (выб.−ген.) |
|---|---:|---:|---:|
| Среднее | {_pm:.4f} | {_sm:.4f} | {_dm:+.4f} |
| Дисперсия | {_pv:.4f} | {_sv:.4f} | {_dv:+.4f} |
"""
    )

    _out = mo.vstack([mo.as_html(_fig), _table])
    plt.close(_fig)
    _out
    return


if __name__ == "__main__":
    app.run()
